scheduled_import_set.partition_script:
(function partitionHash(import_set_row) {

	// Add your code here

	// eg:
	// return import_set_row.u_important_category;
	// This would ensure all rows with the same 'u_important_category' value will be in the same Import Set.

	 return import_set_row.sys_import_row;

})(import_set_row);

scheduled_import_set.post_script:
(function () {
    var prefix = 'DoppelIOCImport: ';
    var property = 'x_doppe_doppel_t_0.import_watermark';

    if (typeof import_set === 'undefined' || !import_set ||
        import_set.getValue('state') !== 'processed') {
        gs.warn(prefix + 'watermark held: import set not processed');
        return;
    }

    var setId = import_set.getUniqueValue();
    var marker = new GlideRecord('x_doppe_doppel_t_0_staging');
    marker.addQuery('sys_import_set', setId);
    marker.addNotNullQuery('u_import_checkpoint');
    marker.setLimit(2);
    marker.query();

    if (!marker.next()) {
        gs.info(prefix + 'no checkpoint to commit');
        return;
    }

    var checkpoint;
    try {
        checkpoint = JSON.parse(marker.getValue('u_import_checkpoint'));
    } catch (e) {
        gs.warn(prefix + 'watermark held: invalid checkpoint');
        return;
    }

    if (marker.hasNext() || !checkpoint ||
        typeof checkpoint.previous !== 'string' ||
        typeof checkpoint.candidate !== 'string' ||
        !checkpoint.candidate || checkpoint.candidate < checkpoint.previous ||
        typeof checkpoint.expectedRows !== 'number' || checkpoint.expectedRows < 1 ||
        marker.getValue('sys_import_state') !== 'ignored') {
        gs.warn(prefix + 'watermark held: checkpoint validation failed');
        return;
    }

    var run = new GlideRecord('sys_import_set_run');
    run.addQuery('set', setId);
    run.addQuery('sys_transform_map.name', 'Doppel Alert to TI Indicator');
    run.setLimit(2);
    run.query();

    if (!run.next() || run.hasNext() ||
        run.getValue('state') !== 'complete' ||
        run.getValue('errors') !== '0' ||
        run.getValue('skipped') !== '0' ||
        Number(run.getValue('total')) !== checkpoint.expectedRows) {
        gs.warn(prefix + 'watermark held: transform outcome did not match checkpoint');
        return;
    }

	var importErrors = new GlideRecord('import_log');
	if (!importErrors.isValidField('import_set') || !importErrors.isValidField('level')) {
		gs.warn(prefix + 'watermark held: Import Log fields unavailable');
		return;
	}

	importErrors.addQuery('import_set', setId);
	importErrors.addQuery('level', '2');
	importErrors.setLimit(1);
	importErrors.query();

	if (importErrors.hasNext()) {
		gs.warn(prefix + 'watermark held: error in Import Log');
		return;
	}

    if (gs.getProperty(property, '') !== checkpoint.previous) {
        gs.warn(prefix + 'watermark held: starting value changed');
        return;
    }

	var rows = new GlideRecord('x_doppe_doppel_t_0_staging');
	rows.addQuery('sys_import_set', setId);
	rows.addNullQuery('u_import_checkpoint');
	rows.addQuery('sys_import_state', 'IN', 'inserted,updated,ignored');
	rows.query();

	if (rows.getRowCount() !== checkpoint.expectedRows - 1) {
		gs.warn(prefix + 'watermark held: staging row outcomes did not match checkpoint');
		return;
	}

	while (rows.next()) {
		rows.setValue('u_doppel_processing_status', 'confirmed');
		if (!rows.update()) {
			gs.error(prefix + 'watermark held: could not confirm staging row');
			return;
		}
	}

	var importer = new x_doppe_doppel_t_0.DoppelIOCImport();
	if (!importer._persistImportBoundary(checkpoint.candidate)) {
		gs.warn(prefix + 'watermark held: could not persist import confirmations');
		return;
	}

	if (checkpoint.candidate === checkpoint.previous) {
		gs.info(prefix + 'watermark unchanged; staging rows confirmed');
		return;
	}

    if (importer._setProperty(property, checkpoint.candidate) &&
        gs.getProperty(property, '') === checkpoint.candidate) {
        gs.info(prefix + 'watermark committed | import_set=' + import_set.getValue('number'));
		importer._pruneImportConfirmations(checkpoint.candidate);
		if (!checkpoint.previous) {
			var config = importer._configRecord();
			if (config && config.getValue('initial_import_since')) {
				config.setValue('initial_import_since', 'NULL');
				config.setWorkflow(false);
				if (!config.update()) {
					gs.warn(prefix + 'could not clear the initial retry window');
				}
			}
		}
    } else {
        gs.error(prefix + 'watermark write could not be verified');
    }
})();
